class Permissions:
    READ = 1
    WRITE = 2
    EXECUTE = 4
    ADMIN = 8

    _NAMES = {1: "READ", 2: "WRITE", 4: "EXECUTE", 8: "ADMIN"}
    _BY_NAME = {"READ": 1, "WRITE": 2, "EXECUTE": 4, "ADMIN": 8}

    def __init__(self, flags=0):
        self.flags = flags

    def grant(self, perm):
        self.flags |= perm

    def revoke(self, perm):
        self.flags &= ~perm

    def has(self, perm):
        return bool(self.flags & perm)

    def to_list(self):
        return [name for val, name in sorted(self._NAMES.items()) if self.flags & val]

    @classmethod
    def from_list(cls, perms):
        flags = 0
        for name in perms:
            flags |= cls._BY_NAME[name]
        return cls(flags)
